function limparData(v:any){if(!v)return '';v=String(v).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m=v.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;if(v.includes('T'))return v.split('T')[0];try{const d=new Date(v);if(!isNaN(d.getTime()))return d.toISOString().split('T')[0]}catch{}return ''}
function fmtData(v:any){const l=limparData(v);if(!l)return '-';return l.split('-').reverse().join('/')}
function statusExame(item:any){const d=limparData(item?.data);const res=(item?.resultado||'').toLowerCase();if(['apto','inapto','apto com restrição','apto com restricao'].includes(res))return 'realizado';if(!d)return 'sem-data';const hoje=new Date().toISOString().split('T')[0];if(d===hoje)return 'hoje';if(d<hoje)return 'vencido';const diff=(new Date(d).getTime()-new Date(hoje).getTime())/(1000*60*60*24);if(diff<=7)return 'proximo';return 'futuro'}
